def _single_package_contract(
    contract_id: str, concrete_kind: str
) -> dict[str, object]:
    return {
        "allowed-artifact-tuples": [
            {
                "role": "primary-package",
                "kind-family": "package",
                "concrete-kind": concrete_kind,
            }
        ],
        "aggregate-rules": {
            "min-artifact-count": 1,
            "max-artifact-count": 1,
            "cross-variant-policy": "forbid",
            "tuple-rules": [
                {
                    "role": "primary-package",
                    "kind-family": "package",
                    "concrete-kind": concrete_kind,
                    "min-count": 1,
                    "max-count": 1,
                }
            ],
        },
        "id": contract_id,
    }


