    inputs = cast(
        "dict[str, object]",
        cast("dict[str, object]", on_block)["workflow_call"]["inputs"],
    )
    jobs = cast("dict[str, object]", workflow["jobs"])
    job = cast("dict[str, object]", next(iter(jobs.values())))
