    step_names = [cast("str", step["name"]) for step in steps]

    setup_dotnet_step = next(
        step for step in steps if step.get("name") == "Setup .NET SDK"
    )
    restore_step = next(
        step for step in steps if step.get("name") == "Restore .NET tools"
    )
