@pytest.mark.parametrize("case", ["stale", "misbound"])
def test_release_completed_rejects_finalized_all_skip_stale_or_misbound_skip_receipts(
    case: str,
) -> None:
    """All-skip reruns must provide current skip receipts bound to the plan."""
