def test_final_uploaded_byte_gate_preserves_unbound_invalid_plan_manifest() -> (
    None
):
    """No-authority invalid-plan summaries stay unbound while uploads bind."""
    scratch = SCRATCH / "final-uploaded-unbound-invalid-plan"
