def _release_shaped_no_publish_matrix(
    plan: Mapping[str, object],
) -> dict[str, object]:
    work_group = cast(
        "dict[str, object]",
        cast("Sequence[object]", plan["work-groups"])[0],
    )
    return {
        **work_group,
        "validation-commands": control._ci_validation_commands(
            plan,
            work_group,
        ),
        "no-publish": True,
    }


