        artifact_ref = cast("str", batch["expected-batch-evidence-bundle-ref"])
        artifact_dir = observed_root / artifact_physical_name(artifact_ref)
        artifact_dir.mkdir()
        (artifact_dir / "batch-evidence-bundle.json").write_text(
            "{",
            encoding="utf-8",
        )

